// ---- 1. 全局声明 (src/types/global.d.ts) ----
// 构建工具注入的常量
// 注意：此文件不能有 import/export，否则变成模块，全局声明失效

/** Vite 构建模式 */
declare const __MODE__: 'development' | 'production' | 'test';

/** 浏览器扩展 */
interface Window {
  __REDUX_DEVTOOLS_EXTENSION__?: typeof import('redux-devtools-extension').composeWithDevTools;
}

// ---- 2. 模块声明：为无类型的第三方库添加类型 ----
// (src/types/some-lib.d.ts)

declare module 'some-untyped-lib' {
  /** 解析配置 */
  interface ParseOptions {
    strict?: boolean;
    timeout?: number;
  }

  /** 解析输入字符串 */
  export function parse(input: string, options?: ParseOptions): Record<string, unknown>;

  /** 版本号 */
  export const VERSION: string;
}

// ---- 3. 模块扩展：给 Express Request 加字段 ----
// (src/types/express.d.ts)

declare module 'express' {
  interface Request {
    user?: { id: string; role: 'admin' | 'user' };
  }
}

// ---- 4. 资源文件类型 ----
// CSS Modules
declare module '*.module.css' {
  const classes: Readonly<Record<string, string>>;
  export default classes;
}

// 普通 CSS（作为 side-effect 导入）
declare module '*.css' {}

// 图片资源
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.svg' {
  import type { ComponentType, SVGProps } from 'react';
  const ReactComponent: ComponentType<SVGProps<SVGSVGElement>>;
  export { ReactComponent };
  export default string;
}

// ---- 5. Vite 环境变量扩展 ----
// (src/types/env.d.ts)

interface ImportMetaEnv {
  readonly VITE_API_URL: string;
  readonly VITE_APP_TITLE: string;
  readonly VITE_SENTRY_DSN?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
